<script>
  const html = document.documentElement;
  const btn  = document.getElementById('themeBtn');
  const sun  = document.getElementById('iconSun');
  const moon = document.getElementById('iconMoon');

  function getStored() {
    try { return localStorage.getItem('theme'); } catch { return null; }
  }
  function resolve(t) {
    if (t === 'light' || t === 'dark') return t;
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }
  function applyTheme(t) {
    const r = resolve(t);
    html.setAttribute('data-theme', r);
    sun.hidden  = (r === 'dark');
    moon.hidden = (r === 'light');
    btn.setAttribute('aria-label', r === 'dark' ? 'Switch to light mode' : 'Switch to dark mode');
    try { localStorage.setItem('theme', r); } catch {}
  }

  applyTheme(getStored());

  btn.addEventListener('click', () => {
    applyTheme(resolve(getStored()) === 'dark' ? 'light' : 'dark');
  });

  const navbar = document.getElementById('navbar');
  const heroEl = document.querySelector('.hero-wrap');
  if (heroEl && navbar) {
    const io = new IntersectionObserver(([e]) => {
      navbar.classList.toggle('scrolled', !e.isIntersecting);
    }, { threshold: 0.05 });
    io.observe(heroEl);
  }
</script>
